def is_prime(n):
    """Return True if n is a prime number (see NB07)."""
    if n < 2:
        return False
    for d in range(2, n):
        if n % d == 0:
            return False
    return True

def primes_less_than(n):
    """Return a list of all prime numbers less than n."""
    result = []
    for i in range(2, n):
        if is_prime(i):
            result.append(i)
    return result

print(primes_less_than(30))

