def first_multiple_of_21(start, stop):
    """Return the first multiple of 21 in range(start, stop), or None."""
    for i in range(start, stop):
        if i % 21 == 0:
            return i

print(first_multiple_of_21(101, 110))
print(first_multiple_of_21(101, 1_000_000_000_000))
